  2	import { builtinTokens } from '../../generated/tokens'
  3	import { contrastRatio } from '../../theme/contrast'
  4	import type { ResolvedTheme, ThemeRole } from '../../theme/types'
  5	
  6	interface Slot {
  7	  readonly key: string
  8	  readonly role: ThemeRole
  9	  readonly raw: string
 10	  readonly background?: string
 11	  readonly minimum?: number
 12	}
 13	const slots: Readonly<Record<string, Slot>> = referenceTheme.slots
 14	export interface ReferenceStyleProjection {
 15	  readonly colors: Readonly<Record<string, string>>
 16	  readonly repairs: readonly {
 17	    readonly slot: string
 18	    readonly original: string
 19	    readonly effective: string
 20	  }[]
 21	}
 22	function composite(raw: string, background?: string): string {
 23	  let hex = raw.slice(1)
 24	  if (hex.length < 5) hex = [...hex].map((char) => char + char).join('')
 25	  if (hex.length === 6) return '#' + hex.toUpperCase()
 26	  if (hex.length !== 8 || !background) throw Error('Unbound reference alpha')
 27	  const alpha = parseInt(hex.slice(6), 16) / 255
 28	  return (
 29	    '#' +
 30	    [0, 2, 4]
 31	      .map((offset) =>
 32	        Math.round(
 33	          parseInt(hex.slice(offset, offset + 2), 16) * alpha +
 34	            parseInt(background.slice(offset + 1, offset + 3), 16) * (1 - alpha),
 35	        )
 36	          .toString(16)
 37	          .padStart(2, '0'),
 38	      )
 39	      .join('')
 40	      .toUpperCase()
 41	  )
 42	}
 43	/** First-party view projection, after the existing resolver; it never selects or persists a theme. */
 44	export function projectReferenceStyles(snapshot: ResolvedTheme): ReferenceStyleProjection {
 45	  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) return { colors: {}, repairs: [] }
 46	  const colors: Record<string, string> = {},
 47	    active = new Set<string>()
 48	  const repairs: { slot: string; original: string; effective: string }[] = []
 49	  const resolve = (name: string): string => {
 50	    if (colors[name]) return colors[name]
 51	    if (active.has(name) || !Object.hasOwn(slots, name))
 52	      throw Error('Invalid reference style dependency')
 53	    active.add(name)
 54	    const slot = slots[name],
 55	      background = slot.background ? resolve(slot.background) : undefined
 56	    const roleChanged = snapshot.colors[slot.role] !== referenceTheme.descriptor.colors[slot.role]
 57	    let color = roleChanged ? snapshot.colors[slot.role] : composite(slot.raw, background)
 58	    if (background && slot.minimum && contrastRatio(color, background) < slot.minimum) {
 59	      const original = color
 60	      const replacement = [
 61	        snapshot.colors[slot.role],
 62	        builtinTokens.themes.dark[slot.role],
 63	        builtinTokens.themes.dark['text.primary'],
 64	        builtinTokens.themes.light['text.primary'],
 65	      ].find((candidate) => contrastRatio(candidate, background) >= slot.minimum!)
 66	      if (!replacement) throw Error('Reference style contrast cannot be established: ' + name)
 67	      color = replacement
 68	      repairs.push({ slot: name, original, effective: color })
 69	    }
 70	    active.delete(name)
 71	    colors[name] = color
 72	    return color
 73	  }
 74	  for (const name of Object.keys(slots)) resolve(name)
 75	  return { colors: Object.freeze(colors), repairs: Object.freeze(repairs) }
 76	}
