 78	export function applyReferencePreset(root: HTMLElement, snapshot: ResolvedTheme): void {
 79	  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) {
 80	    if (root.dataset.fradeReference === 'vscode-dark-2026') {
 81	      root.removeAttribute('data-frade-reference')
 82	      for (const name of Object.keys(slots)) root.style.removeProperty('--frade-vscode-' + name)
 83	    }
 84	    return
 85	  }
 86	  const projection = projectReferenceStyles(snapshot)
 87	  for (const [name, color] of Object.entries(projection.colors))
 88	    root.style.setProperty('--frade-vscode-' + name, color)
 89	  root.dataset.fradeReference = 'vscode-dark-2026'
 90	}

