  9	export type DiagramEditorProps = {
 10	  embedded?: boolean
 11	  onGraphReady?: (graph: Graph) => void | (() => void)
 12	  requestDocumentName?: (currentName: string) => string | null | Promise<string | null>
 13	}
 14	const newMetadata = () => ({ id: crypto.randomUUID(), name: 'diagram' })
 15	let number = 1
 16	export function DiagramEditor({ onGraphReady, requestDocumentName, embedded }: DiagramEditorProps) {
 17	  const host = useRef<HTMLDivElement>(null)
 18	  const graph = useRef<Graph | null>(null)
 19	  const metadata = useRef<DiagramDocument['metadata']>(newMetadata())
 20	  const readGeneration = useRef(0)
 21	  const [selected, setSelected] = useState<string | null>(null)
 22	  const [gridVisible, setGridVisible] = useState(true)
 23	  const [error, setError] = useState('')
 24	  const [opening, setOpening] = useState(false)
 25	  const fileInput = useRef<HTMLInputElement>(null)
 26	  useEffect(() => {
 27	    const generationRef = readGeneration
 28	    if (!host.current) return
 29	    const instance = createGraph(host.current)
 30	    graph.current = instance
 31	    const resize = () => instance.resize?.(host.current!.clientWidth, host.current!.clientHeight)
 32	    resize()
 33	    const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(resize)
 34	    observer?.observe(host.current)
 35	    const disposeHostIntegration = onGraphReady?.(instance)
 36	    instance.on('selection:changed', ({ selected }) => {
 37	      instance.getEdges().forEach((edge) => edge.removeTools())
 38	      const cell = selected[0]
 39	      if (cell?.isEdge()) installSegmentAdapter(cell)
 40	      setSelected(cell?.id ?? null)
 41	    })
 42	    return () => {
 43	      generationRef.current++
 44	      observer?.disconnect()
 45	      disposeHostIntegration?.()
 46	      instance.dispose()
 47	      graph.current = null
 48	    }
 49	  }, [onGraphReady])
 50	  const add = (shape: DiagramShape) => {
 51	    const instance = graph.current
 52	    if (!instance) return
 53	    let id: string
 54	    do {
 55	      id = 'node-' + number++
 56	    } while (instance.getCellById(id))
 57	    instance.addNode(
 58	      nodeToCell({
 59	        id,
 60	        shape,
 61	        x: 120 + number * 12,
 62	        y: 120 + number * 12,
 63	        width: 150,
 64	        height: 72,
 65	        label: shape === 'text' ? 'Text' : 'New shape',
 66	      }),
 67	    )
 68	  }
 69	  const remove = () => {
 70	    if (selected) graph.current?.removeCell(selected)
 71	  }
 72	  const zoom = (amount: number) => graph.current?.zoom(amount)
 73	  const toggleGrid = () => {
 74	    const next = !gridVisible
 75	    setGridVisible(next)
 76	    if (next) graph.current?.showGrid()
 77	    else graph.current?.hideGrid()
 78	  }
 79	  const save = async (saveAs = false) => {
 80	    const instance = graph.current
 81	    if (!instance) return
 82	    const generation = readGeneration.current
 83	    let next = metadata.current
 84	    try {
 85	      if (saveAs) {
 86	        const name = requestDocumentName
 87	          ? await requestDocumentName(next.name)
 88	          : window.prompt('Document name', next.name)
 89	        if (generation !== readGeneration.current || graph.current !== instance) return
 90	        if (name === null) return
 91	        if (!name.trim()) {
 92	          setError('Document name must not be empty.')
 93	          return
 94	        }
 95	        next = { ...next, name: name.trim() }
 96	      }
 97	      const { tx, ty } = instance.translate()
 98	      downloadDocument(
 99	        graphToDocument(instance, next, { zoom: instance.zoom(), pan: { x: tx, y: ty } }),
100	      )
101	      metadata.current = next
102	      setError('')
103	    } catch (error) {
104	      setError(error instanceof Error ? error.message : 'Could not save the document.')
105	    }
106	  }
107	  const createNew = () => {
108	    const instance = graph.current
109	    if (!instance) return
110	    readGeneration.current++
111	    setOpening(false)
112	    const next = newMetadata()
113	    loadDocument(instance, {
114	      format: 'frade-draw',
115	      version: 1,
116	      metadata: next,
117	      graph: { nodes: [], edges: [] },
118	    })
119	    metadata.current = next
120	    setSelected(null)
121	    setError('')
122	  }
123	  const open = async (event: React.ChangeEvent<HTMLInputElement>) => {
124	    const file = event.target.files?.[0],
125	      instance = graph.current
126	    event.target.value = ''
127	    if (!file || !instance) return
128	    const generation = ++readGeneration.current
129	    setOpening(true)
130	    try {
131	      const model = await readDocument(file)
132	      if (generation !== readGeneration.current || graph.current !== instance) return
133	      loadDocument(instance, model)
134	      metadata.current = model.metadata
135	      setSelected(null)
136	      setError('')
137	    } catch (error) {
138	      if (generation === readGeneration.current)
139	        setError(error instanceof Error ? error.message : 'Could not open the document.')
140	    } finally {
141	      if (generation === readGeneration.current) setOpening(false)
142	    }
143	  }
144	  return (
145	    <main>
146	      <header>
147	        <strong>Frade Draw</strong>
148	        {!embedded && (
149	          <>
150	            <button onClick={createNew}>New</button>
151	            <button onClick={() => save()} disabled={opening}>
152	              Save
153	            </button>
154	            <button onClick={() => save(true)} disabled={opening}>
155	              Save As
156	            </button>
157	            <button onClick={() => fileInput.current?.click()}>Open</button>
158	            <input
159	              ref={fileInput}
160	              type="file"
161	              accept="application/json,.json"
162	              aria-label="Open diagram"
163	              hidden
164	              onChange={open}
165	            />
166	          </>
167	        )}
168	        <button onClick={remove} disabled={!selected || opening}>
169	          Delete
170	        </button>
171	        <button onClick={() => graph.current?.undo()} disabled={opening}>
172	          Undo
173	        </button>
174	        <button onClick={() => graph.current?.redo()} disabled={opening}>
175	          Redo
176	        </button>
177	        <button onClick={() => zoom(0.1)}>Zoom +</button>
178	        <button onClick={() => zoom(-0.1)}>Zoom −</button>
179	        <button onClick={() => graph.current?.zoomToFit({ padding: 30 })}>Fit</button>
180	        <button onClick={toggleGrid}>Grid</button>
181	        <button onClick={() => graph.current?.exportSVG('diagram.svg')}>SVG</button>
182	        <button onClick={() => graph.current?.exportPNG('diagram.png')}>PNG</button>
183	      </header>
184	      <aside>
185	        {diagramShapes.map((shape) => (
186	          <button key={shape} disabled={opening} onClick={() => add(shape)}>
187	            {shape}
188	          </button>
189	        ))}
190	        {error && <p role="alert">{error}</p>}
191	      </aside>
192	      <div className="canvas" ref={host} style={opening ? { pointerEvents: 'none' } : undefined} />
193	    </main>
194	  )
195	}
